  {
    "page_number": 10,
    "blocks": [
      {
        "evidence_id": "ev_p10_b127",
        "type": "heading",
        "section_path": [],
        "bbox": [
          0.3611,
          0.066,
          0.6454,
          0.0787
        ],
        "text": "NASA-STD-8739.14 - 2020-06-02"
      },
      {
        "evidence_id": "ev_p10_b128",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.0984,
          0.8819,
          0.1464
        ],
        "text": "Catastrophic Hazard: A hazard, condition or event that could result in a mishap causing fatal injury to personnel and/or loss of spacecraft (payload), launch vehicle, or ground facility."
      },
      {
        "evidence_id": "ev_p10_b129",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.1659,
          0.8659,
          0.2138
        ],
        "text": "Certificate of Conformance (CoC): A document signed by the supplier to affirm the product has met the requirements of the relevant specification(s), contract(s), and any other applicable regulations."
      },
      {
        "evidence_id": "ev_p10_b130",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.2333,
          0.884,
          0.2986
        ],
        "text": "Commingling:  A storage state where hardware (e.g., fasteners, inserts, etc.) from two or more different lots are co-located or stored in the same bin or other holding container resulting in loss of traceability to the quality data, certification documentation, and records."
      },
      {
        "evidence_id": "ev_p10_b131",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.3182,
          0.8862,
          0.3487
        ],
        "text": "Critical Hazard: A hazard, condition or event that may cause severe injury or occupational illness, or major property damage to facilities, systems, or flight hardware."
      },
      {
        "evidence_id": "ev_p10_b132",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.3682,
          0.8642,
          0.3987
        ],
        "text": "Distributor:  An enterprise that stocks the products of various manufacturers for resale and does not engage in manufacturing activity."
      },
      {
        "evidence_id": "ev_p10_b133",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.4182,
          0.8816,
          0.4661
        ],
        "text": "Hardware Developer:  Organization directly responsible for the design, manufacture, analysis, test, and safety compliance documentation of the hardware (Reference NASASTD-5020, Requirements for Threaded Fastening Systems in Spaceflight Hardware)."
      },
      {
        "evidence_id": "ev_p10_b134",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.4856,
          0.8196,
          0.5161
        ],
        "text": "Hazard: A state or a set of conditions, internal or external to a system that has the potential to cause harm."
      },
      {
        "evidence_id": "ev_p10_b135",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.5356,
          0.8678,
          0.5835
        ],
        "text": "Lot: A collection of units or items which are of the same configuration, fabricated from the same mill heat of material, formed, machined, heat treated, and finished at the same time, using the same processes."
      },
      {
        "evidence_id": "ev_p10_b136",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.6031,
          0.7868,
          0.6161
        ],
        "text": "Manufacturer: An enterprise that manufacturers fasteners from raw materials."
      },
      {
        "evidence_id": "ev_p10_b137",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.6356,
          0.8718,
          0.6661
        ],
        "text": "Manufacturer's Test Report (MTR):  A document that is produced by the manufacturer to report information required by the applicable technical and procurement specification."
      },
      {
        "evidence_id": "ev_p10_b138",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.6856,
          0.8858,
          0.7335
        ],
        "text": "The information typically includes lot number, manufacturing date, lot quantity, raw material heat number, chemical composition, mechanical properties as determined by testing, and metallurgical test results. An MTR may also be referred to as a Certificate of Analysis (CoA)."
      },
      {
        "evidence_id": "ev_p10_b139",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.7531,
          0.8648,
          0.7836
        ],
        "text": "Second-Party Audit: An external audit performed on a supplier by a customer or by a contracted organization on behalf of a customer."
      },
      {
        "evidence_id": "ev_p10_b140",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.8031,
          0.8819,
          0.851
        ],
        "text": "Specification:  A document that specifies, in a complete, precise, verifiable manner, the requirements, design, behavior or other characteristics of a system or component, and, often the procedures for determining whether these procedures have been satisfied."
      },
      {
        "evidence_id": "ev_p10_b141",
        "type": "paragraph",
        "section_path": [],
        "bbox": [
          0.1912,
          0.8705,
          0.658,
          0.8836
        ],
        "text": "Supplier: Generic term for distributors and manufacturers."
      },
      {
        "evidence_id": "ev_p10_b142",
        "type": "footer",
        "section_path": [],
        "bbox": [
          0.4458,
          0.9405,
          0.5591,
          0.9536
        ],
        "text": "Page 10 of 16"
      }
    ],
    "tables": []
